#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>

int regNumber(const std::string& name)
{
    static const char* names[]{"ax", "cx", "dx", "bx", "sp", "bp", "si", "di"};
    for (int i{0}; i < 8; ++i)
        if (name.substr(1) == names[i]) return i;
    return -1;
}

int main()
{
    std::printf("%d\n", regNumber("rcx"));
}
